 21	package pousada;
 22	
 23	import com.fasterxml.jackson.databind.JsonNode;
 24	import com.fasterxml.jackson.databind.ObjectMapper;
 25	import io.javalin.Javalin;
 26	import io.javalin.http.Context;
 27	import io.javalin.json.JavalinJackson;
 28	import pousada.Domain.*;
 29	
 30	import java.time.LocalDate;
 31	import java.time.YearMonth;
 32	import java.time.format.DateTimeParseException;
 33	import java.util.LinkedHashMap;
 34	import java.util.List;
 35	import java.util.Map;
 36	import java.util.regex.Pattern;
 37	
 38	public final class App {
 39	    private static final ObjectMapper MAPPER = new ObjectMapper();
 40	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
 41	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
 42	    private static final String CSV = "text/csv; charset=utf-8";
 43	
 44	    private final Service service;
 45	
 46	    public App(Service service) {
 47	        this.service = service;
 48	    }
 49	
 50	    public Javalin create() {
 51	        Javalin app = Javalin.create(cfg -> {
 52	            cfg.showJavalinBanner = false;
 53	            cfg.jsonMapper(new JavalinJackson(MAPPER, false));
 54	        });
 55	
 56	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
 57	        app.exception(Exception.class, (e, ctx) -> {
 58	            e.printStackTrace();
 59	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 60	        });
 61	        app.error(404, ctx -> {
 62	            String type = ctx.res().getContentType();
 63	            if (type == null || !type.startsWith("application/json")) {
 64	                error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
 65	            }
 66	        });
 67	
 68	        app.get("/rooms", ctx -> ctx.json(service.rooms().stream().map(App::roomJson).toList()));
 69	
 70	        app.post("/reservations", ctx -> ctx.status(201).json(reservationJson(service.create(parseNew(ctx)))));
 71	        app.get("/reservations/{id}", ctx -> ctx.json(reservationJson(service.reservation(id(ctx)))));
 72	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(reservationJson(service.confirm(id(ctx)))));
 73	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(reservationJson(service.cancel(id(ctx)))));
 74	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(reservationJson(service.checkIn(id(ctx)))));
 75	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(documentJson(service.checkOut(id(ctx)))));
 76	        app.get("/reservations/{id}/document", ctx -> ctx.json(documentJson(service.document(id(ctx)))));
 77	
 78	        app.get("/messages", ctx -> ctx.json(service.messages().stream().map(App::messageJson).toList()));
 79	
 80	        app.get("/reports/occupancy", ctx -> {
 81	            String date = ctx.queryParam("date");
 82	            if (date == null || !DATE.matcher(date).matches()) throw ApiException.invalid("Parâmetro date inválido (use AAAA-MM-DD)");
 83	            LocalDate d;
 84	            try {
 85	                d = LocalDate.parse(date);
 86	            } catch (DateTimeParseException e) {
 87	                throw ApiException.invalid("Parâmetro date inválido (use AAAA-MM-DD)");
 88	            }
 89	            ctx.contentType(CSV).result(service.occupancyCsv(d));
 90	        });
 91	        app.get("/reports/revenue", ctx -> {
 92	            String month = ctx.queryParam("month");
 93	            if (month == null || !MONTH.matcher(month).matches()) throw ApiException.invalid("Parâmetro month inválido (use AAAA-MM)");
 94	            YearMonth m;
 95	            try {
 96	                m = YearMonth.parse(month);
 97	            } catch (DateTimeParseException e) {
 98	                throw ApiException.invalid("Parâmetro month inválido (use AAAA-MM)");
 99	            }
100	            ctx.contentType(CSV).result(service.revenueCsv(m));
101	        });
102	        return app;
103	    }
104	
105	    // ---- entrada ----
106	
107	    private static long id(Context ctx) {
108	        try {
109	            return Long.parseLong(ctx.pathParam("id"));
110	        } catch (NumberFormatException e) {
111	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada: " + ctx.pathParam("id"));
112	        }
113	    }
114	
115	    private static Service.NewReservation parseNew(Context ctx) {
116	        JsonNode body;
117	        try {
118	            body = MAPPER.readTree(ctx.body());
119	        } catch (Exception e) {
120	            throw ApiException.invalid("Corpo da requisição não é um JSON válido");
121	        }
122	        if (body == null || !body.isObject()) throw ApiException.invalid("Corpo da requisição deve ser um objeto JSON");
123	
124	        int roomNumber = integer(body, "roomNumber");
125	        String name = text(body, "guestName", true);
126	        String email = text(body, "guestEmail", true);
127	        if (!email.contains("@")) throw ApiException.invalid("guestEmail inválido");
128	        LocalDate checkIn = date(body, "checkIn");
129	        LocalDate checkOut = date(body, "checkOut");
130	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("checkOut deve ser depois de checkIn");
131	        int guests = integer(body, "guests");
132	        if (guests < 1) throw ApiException.invalid("guests deve ser de pelo menos 1");
133	        RatePlan plan;
134	        try {
135	            plan = RatePlan.valueOf(text(body, "ratePlan", true));
136	        } catch (IllegalArgumentException e) {
137	            throw ApiException.invalid("ratePlan inválido (STANDARD ou NON_REFUNDABLE)");
138	        }
139	
140	        String cpf = text(body, "guestCpf", false);
141	        String cnpj = text(body, "companyCnpj", false);
142	        String company = text(body, "companyName", false);
143	        String passport = text(body, "guestPassport", false);
144	        String country = text(body, "guestCountry", false);
145	        boolean individual = cpf != null && cnpj == null && company == null && passport == null && country == null;
146	        boolean corporate = cnpj != null && company != null && cpf == null && passport == null && country == null;
147	        boolean foreign = passport != null && country != null && cpf == null && cnpj == null && company == null;
148	        if (!(individual || corporate || foreign)) {
149	            throw ApiException.invalid("Informe guestCpf, ou companyCnpj com companyName, ou guestPassport com guestCountry");
150	        }
151	        return new Service.NewReservation(roomNumber, name, email,
152	                Identification.from(cpf, cnpj, company, passport, country), checkIn, checkOut, guests, plan);
153	    }
154	
155	    /** Texto opcional ou obrigatório; vazio conta como ausente. */
156	    private static String text(JsonNode body, String field, boolean required) {
157	        JsonNode n = body.get(field);
158	        if (n == null || n.isNull()) {
159	            if (required) throw ApiException.invalid("Campo obrigatório: " + field);
160	            return null;
161	        }
162	        if (!n.isTextual()) throw ApiException.invalid("Campo " + field + " deve ser texto");
163	        String s = n.asText().trim();
164	        if (s.isEmpty()) {
165	            if (required) throw ApiException.invalid("Campo obrigatório: " + field);
166	            return null;
167	        }
168	        return s;
169	    }
170	
171	    private static int integer(JsonNode body, String field) {
172	        JsonNode n = body.get(field);
173	        if (n == null || n.isNull()) throw ApiException.invalid("Campo obrigatório: " + field);
174	        if (!n.isIntegralNumber() || !n.canConvertToInt()) throw ApiException.invalid("Campo " + field + " deve ser um número inteiro");
175	        return n.intValue();
176	    }
177	
178	    private static LocalDate date(JsonNode body, String field) {
179	        String s = text(body, field, true);
180	        if (!DATE.matcher(s).matches()) throw ApiException.invalid("Campo " + field + " deve estar no formato AAAA-MM-DD");
181	        try {
182	            return LocalDate.parse(s);
183	        } catch (DateTimeParseException e) {
184	            throw ApiException.invalid("Campo " + field + " é uma data inválida");
185	        }
186	    }
187	
188	    // ---- saída ----
189	
190	    private static void error(Context ctx, int status, String code, String message) {
191	        Map<String, Object> m = new LinkedHashMap<>();
192	        m.put("error", code);
193	        m.put("message", message);
194	        ctx.status(status).json(m);
195	    }
196	
197	    private static Map<String, Object> roomJson(Room r) {
198	        Map<String, Object> m = new LinkedHashMap<>();
199	        m.put("number", r.number());
200	        m.put("type", r.type());
201	        m.put("capacity", r.capacity());
202	        m.put("nightlyRate", r.nightlyRate());
203	        return m;
204	    }
205	
206	    private static void identification(Map<String, Object> m, Identification i) {
207	        m.put("guestCpf", i.cpf());
208	        m.put("companyCnpj", i.cnpj());
209	        m.put("companyName", i.companyName());
210	        m.put("guestPassport", i.passport());
211	        m.put("guestCountry", i.country());
212	    }
213	
214	    private static Map<String, Object> reservationJson(Reservation r) {
215	        Map<String, Object> m = new LinkedHashMap<>();
216	        m.put("id", r.id());
217	        m.put("roomNumber", r.roomNumber());
218	        m.put("guestName", r.guestName());
219	        m.put("guestEmail", r.guestEmail());
220	        identification(m, r.identification());
221	        m.put("checkIn", r.checkIn().toString());
222	        m.put("checkOut", r.checkOut().toString());
223	        m.put("guests", r.guests());
224	        m.put("ratePlan", r.ratePlan());
225	        m.put("nights", r.nights());
226	        m.put("subtotal", r.subtotal());
227	        m.put("discount", r.discount());
228	        m.put("total", r.total());
229	        m.put("status", r.status());
230	        m.put("amountPaid", r.amountPaid());
231	        m.put("refund", r.refund());
232	        return m;
233	    }
234	
235	    private static Map<String, Object> documentJson(Service.Document d) {
236	        Identification.Receipt r = d.receipt();
237	        Map<String, Object> m = new LinkedHashMap<>();
238	        m.put("title", d.reservation().identification().title());
239	        m.put("reservationId", r.reservationId());
240	        m.put("guestName", r.guestName());
241	        identification(m, d.reservation().identification());
242	        m.put("roomNumber", r.roomNumber());
243	        m.put("roomType", r.roomType());
244	        m.put("checkIn", r.checkIn().toString());
245	        m.put("checkOut", r.checkOut().toString());
246	        m.put("nights", r.nights());
247	        m.put("subtotal", r.subtotal());
248	        m.put("discount", r.discount());
249	        m.put("total", r.total());
250	        m.put("text", d.text());
251	        return m;
252	    }
253	
254	    private static Map<String, Object> messageJson(Message m) {
255	        Map<String, Object> o = new LinkedHashMap<>();
256	        o.put("id", m.id());
257	        o.put("channel", m.channel());
258	        o.put("to", m.to());
259	        o.put("subject", m.subject());
260	        o.put("body", m.body());
261	        return o;
262	    }
263	}
264	package pousada;
265	
266	public class ApiException extends RuntimeException {
267	    public final int status;
268	    public final String code;
269	
270	    public ApiException(int status, String code, String message) {
271	        super(message);
272	        this.status = status;
273	        this.code = code;
274	    }
275	
276	    public static ApiException invalid(String message) {
277	        return new ApiException(400, "INVALID_REQUEST", message);
278	    }
279	
280	    public static ApiException notAllowed(String message) {
281	        return new ApiException(409, "OPERATION_NOT_ALLOWED", message);
282	    }
283	}

