100	                    INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
101	                      guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights, subtotal, discount,
102	                      total, status, amount_paid)
103	                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id""")) {
104	                int k = 1;
105	                ps.setInt(k++, room.number());
106	                ps.setString(k++, n.guestName());
107	                ps.setString(k++, n.guestEmail());
108	                ps.setString(k++, i.cpf());
109	                ps.setString(k++, i.cnpj());
110	                ps.setString(k++, i.companyName());
111	                ps.setString(k++, i.passport());
112	                ps.setString(k++, i.country());
113	                ps.setDate(k++, Date.valueOf(n.checkIn()));
114	                ps.setDate(k++, Date.valueOf(n.checkOut()));
115	                ps.setInt(k++, n.guests());
116	                ps.setString(k++, n.ratePlan().name());
117	                ps.setInt(k++, q.nights());
118	                ps.setBigDecimal(k++, q.subtotal());
119	                ps.setBigDecimal(k++, q.discount());
120	                ps.setBigDecimal(k++, q.total());
121	                ps.setString(k++, Status.PENDING.name());
122	                ps.setBigDecimal(k, Money.ZERO);
123	                try (ResultSet rs = ps.executeQuery()) {
124	                    rs.next();
125	                    return load(c, rs.getLong(1), false);
126	                }
127	            }
128	        });
129	    }
130	
131	    public Reservation confirm(long id) {
132	        return tx(c -> {
133	            Reservation r = load(c, id, true);
134	            require(r.status() == Status.PENDING, "Só é possível confirmar uma reserva pendente");
135	            update(c, id, "status = 'CONFIRMED', amount_paid = total");
136	            Reservation confirmed = load(c, id, false);
137	            Document doc = document(c, confirmed);
138	            String body = "Olá, " + confirmed.guestName() + "!\n\n"
139	                    + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
140	                    + doc.text() + "\n\n"
141	                    + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
142	                    + "Até breve!";
143	            try (PreparedStatement ps = c.prepareStatement(
144	                    "INSERT INTO messages (channel, recipient, subject, body) VALUES ('EMAIL', ?, ?, ?)")) {
145	                ps.setString(1, confirmed.guestEmail());
146	                ps.setString(2, "Reserva confirmada - Pousada Maré Alta");
147	                ps.setString(3, body);
148	                ps.executeUpdate();
149	            }
150	            return confirmed;
151	        });
152	    }
153	
154	    public Reservation cancel(long id) {
155	        return tx(c -> {
156	            Reservation r = load(c, id, true);
157	            require(r.status() == Status.PENDING || r.status() == Status.CONFIRMED,
158	                    "Só é possível cancelar uma reserva pendente ou confirmada");
159	            // pendente não tem nada pago; no plano não reembolsável nada é devolvido
160	            BigDecimal refund = r.ratePlan() == RatePlan.STANDARD ? r.amountPaid() : Money.ZERO;
161	            try (PreparedStatement ps = c.prepareStatement(
162	                    "UPDATE reservations SET status = 'CANCELLED', refund = ? WHERE id = ?")) {
163	                ps.setBigDecimal(1, refund);
164	                ps.setLong(2, id);
165	                ps.executeUpdate();
166	            }
167	            return load(c, id, false);
168	        });
169	    }
170	
171	    public Reservation checkIn(long id) {
172	        return tx(c -> {
173	            Reservation r = load(c, id, true);
174	            require(r.status() == Status.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada");
175	            update(c, id, "status = 'CHECKED_IN'");
176	            return load(c, id, false);
177	        });
178	    }
179	
180	    public Document checkOut(long id) {
181	        return tx(c -> {
182	            Reservation r = load(c, id, true);
183	            require(r.status() == Status.CHECKED_IN, "Só é possível fazer check-out de uma reserva com check-in");
184	            update(c, id, "status = 'CHECKED_OUT'");
185	            return document(c, load(c, id, false));
186	        });
187	    }
188	
189	    public Document document(long id) {
190	        return tx(c -> {
191	            Reservation r = load(c, id, false);
192	            require(r.isPaid(), "Só existe documento para reserva paga");
193	            return document(c, r);
194	        });
195	    }
196	
197	    // ---- relatórios ----
198	
199	    public String occupancyCsv(LocalDate date) {
200	        return tx(c -> {
201	            StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
202	            int occupied = 0;
203	            try (PreparedStatement ps = c.prepareStatement("""
204	                    SELECT r.room_number, m.type, r.id, r.check_in, r.check_out
205	                    FROM reservations r JOIN rooms m ON m.number = r.room_number
206	                    WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND r.check_in <= ? AND r.check_out > ?
207	                    ORDER BY r.room_number, r.id""")) {
208	                ps.setDate(1, Date.valueOf(date));
209	                ps.setDate(2, Date.valueOf(date));
210	                try (ResultSet rs = ps.executeQuery()) {
211	                    while (rs.next()) {
212	                        occupied++;
213	                        sb.append(rs.getInt(1)).append(',').append(rs.getString(2)).append(',').append(rs.getLong(3))
214	                          .append(',').append(rs.getDate(4).toLocalDate()).append(',').append(rs.getDate(5).toLocalDate())
215	                          .append('\n');
216	                    }
217	                }
218	            }
219	            int total;
220	            try (Statement st = c.createStatement(); ResultSet rs = st.executeQuery("SELECT count(*) FROM rooms")) {
221	                rs.next();
222	                total = rs.getInt(1);
223	            }
224	            return sb.append("total,").append(occupied).append('/').append(total).append('\n').toString();
225	        });
226	    }
227	
228	    public String revenueCsv(YearMonth month) {
229	        return tx(c -> {
230	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
231	            BigDecimal sum = Money.ZERO;
232	            try (PreparedStatement ps = c.prepareStatement("""
233	                    SELECT id, room_number, check_in, check_out, status, amount_paid - COALESCE(refund, 0)
234	                    FROM reservations
235	                    WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0
236	                    ORDER BY check_in, id""")) {
237	                ps.setDate(1, Date.valueOf(month.atDay(1)));
238	                ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
239	                try (ResultSet rs = ps.executeQuery()) {
240	                    while (rs.next()) {
241	                        BigDecimal amount = Money.round(rs.getBigDecimal(6));
242	                        sum = sum.add(amount);
243	                        sb.append(rs.getLong(1)).append(',').append(rs.getInt(2)).append(',')
244	                          .append(rs.getDate(3).toLocalDate()).append(',').append(rs.getDate(4).toLocalDate()).append(',')
245	                          .append(rs.getString(5)).append(',').append(Money.plain(amount)).append('\n');
246	                    }
247	                }
248	            }
249	            return sb.append("total,").append(Money.plain(sum)).append('\n').toString();
250	        });
251	    }
252	
253	    // ---- internos ----
254	
255	    private static void require(boolean ok, String message) {
256	        if (!ok) throw ApiException.notAllowed(message);
257	    }
258	
259	    private static void update(Connection c, long id, String set) throws SQLException {
260	        try (PreparedStatement ps = c.prepareStatement("UPDATE reservations SET " + set + " WHERE id = ?")) {
261	            ps.setLong(1, id);
262	            ps.executeUpdate();
263	        }
264	    }
265	
266	    private Document document(Connection c, Reservation r) throws SQLException {
267	        Room room;
268	        try (PreparedStatement ps = c.prepareStatement(
269	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?")) {
270	            ps.setInt(1, r.roomNumber());
271	            try (ResultSet rs = ps.executeQuery()) {
272	                rs.next();
273	                room = room(rs);
274	            }
275	        }
276	        Identification.Receipt receipt = new Identification.Receipt(r.id(), r.guestName(), room.number(), room.type(),
277	                r.checkIn(), r.checkOut(), r.nights(), r.subtotal(), r.discount(), r.total());
278	        return new Document(r, room, receipt, r.identification().render(receipt));
279	    }
280	
281	    private static Room room(ResultSet rs) throws SQLException {
282	        return new Room(rs.getInt(1), RoomType.valueOf(rs.getString(2)), rs.getInt(3), Money.round(rs.getBigDecimal(4)));
283	    }
284	
285	    private static Reservation load(Connection c, long id, boolean lock) throws SQLException {
286	        try (PreparedStatement ps = c.prepareStatement(
287	                "SELECT " + RES_COLS + " FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : ""))) {
288	            ps.setLong(1, id);
289	            try (ResultSet rs = ps.executeQuery()) {
290	                if (!rs.next()) throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada: " + id);
291	                BigDecimal refund = rs.getBigDecimal(20);
292	                return new Reservation(rs.getLong(1), rs.getInt(2), rs.getString(3), rs.getString(4),
293	                        Identification.from(rs.getString(5), rs.getString(6), rs.getString(7), rs.getString(8), rs.getString(9)),
294	                        rs.getDate(10).toLocalDate(), rs.getDate(11).toLocalDate(), rs.getInt(12),
295	                        RatePlan.valueOf(rs.getString(13)), rs.getInt(14),
296	                        Money.round(rs.getBigDecimal(15)), Money.round(rs.getBigDecimal(16)), Money.round(rs.getBigDecimal(17)),
297	                        Status.valueOf(rs.getString(18)), Money.round(rs.getBigDecimal(19)),
298	                        refund == null ? null : Money.round(refund));
299	            }
300	        }
301	    }
302	}
