308	import java.sql.Connection;
309	import java.sql.SQLException;
310	import java.sql.Statement;
311	
312	public final class Db implements AutoCloseable {
313	    private final HikariDataSource ds;
314	
315	    public interface TxWork<T> {
316	        T run(Connection c) throws SQLException;
317	    }
318	
319	    public Db(String url, String user, String password) {
320	        HikariConfig cfg = new HikariConfig();
321	        cfg.setJdbcUrl(url);
322	        cfg.setUsername(user);
323	        cfg.setPassword(password);
324	        cfg.setMaximumPoolSize(10);
325	        cfg.setInitializationFailTimeout(-1); // a conexão é validada em init(), com tentativas
326	        this.ds = new HikariDataSource(cfg);
327	    }
328	
329	    /** Espera o banco ficar disponível e cria o que faltar (banco começa vazio). */
330	    public void init() {
331	        long deadline = System.currentTimeMillis() + 60_000;
332	        while (true) {
333	            try {
334	                tx(c -> {
335	                    try (Statement st = c.createStatement()) {
336	                        // serializa a criação se vários processos sobem juntos
337	                        st.execute("SELECT pg_advisory_xact_lock(727274)");
338	                        st.execute(SCHEMA);
339	                        st.execute("""
340	                                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
341	                                  (101, 'STANDARD', 2, 249.90),
342	                                  (102, 'STANDARD', 2, 249.90),
343	                                  (201, 'DELUXE',   3, 389.90),
344	                                  (202, 'DELUXE',   3, 389.90),
345	                                  (301, 'SUITE',    4, 579.90)
346	                                ON CONFLICT (number) DO NOTHING""");
347	                    }
348	                    return null;
349	                });
350	                return;
351	            } catch (SQLException e) {
352	                if (System.currentTimeMillis() > deadline) {
353	                    throw new IllegalStateException("Banco de dados indisponível: " + e.getMessage(), e);
354	                }
355	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
356	            }
357	        }
358	    }
359	
360	    public <T> T tx(TxWork<T> work) throws SQLException {
361	        try (Connection c = ds.getConnection()) {
362	            c.setAutoCommit(false);
363	            try {
364	                T result = work.run(c);
365	                c.commit();
366	                return result;
367	            } catch (SQLException | RuntimeException e) {
368	                c.rollback();
369	                throw e;
370	            }
371	        }
372	    }
373	
374	    @Override
375	    public void close() {
376	        ds.close();
377	    }
378	
379	    private static final String SCHEMA = """
380	            CREATE TABLE IF NOT EXISTS rooms (
381	              number       INTEGER PRIMARY KEY,
382	              type         TEXT NOT NULL,
383	              capacity     INTEGER NOT NULL,
384	              nightly_rate NUMERIC(12,2) NOT NULL
385	            );
386	            CREATE TABLE IF NOT EXISTS reservations (
387	              id             BIGSERIAL PRIMARY KEY,
388	              room_number    INTEGER NOT NULL REFERENCES rooms(number),
389	              guest_name     TEXT NOT NULL,
390	              guest_email    TEXT NOT NULL,
391	              guest_cpf      TEXT,
392	              company_cnpj   TEXT,
393	              company_name   TEXT,
394	              guest_passport TEXT,
395	              guest_country  TEXT,
396	              check_in       DATE NOT NULL,
397	              check_out      DATE NOT NULL,
398	              guests         INTEGER NOT NULL,
399	              rate_plan      TEXT NOT NULL,
400	              nights         INTEGER NOT NULL,
401	              subtotal       NUMERIC(12,2) NOT NULL,
402	              discount       NUMERIC(12,2) NOT NULL,
403	              total          NUMERIC(12,2) NOT NULL,
404	              status         TEXT NOT NULL,
405	              amount_paid    NUMERIC(12,2) NOT NULL,
406	              refund         NUMERIC(12,2)
407	            );
408	            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in, check_out);
409	            CREATE TABLE IF NOT EXISTS messages (
410	              id        BIGSERIAL PRIMARY KEY,
411	              channel   TEXT NOT NULL,
412	              recipient TEXT NOT NULL,
413	              subject   TEXT NOT NULL,
414	              body      TEXT NOT NULL
415	            );""";
416	}

