  3	import java.math.BigDecimal;
  4	import java.time.LocalDate;
  5	import java.time.format.DateTimeFormatter;
  6	
  7	/**
  8	 * Como o hóspede se identifica. Cada forma sabe emitir o próprio documento
  9	 * (comprovante, fatura, booking receipt...). Para um novo tipo de documento
 10	 * (ex.: agência de turismo), basta uma nova implementação e o seu mapeamento
 11	 * em {@link #from} / na persistência.
 12	 */
 13	public interface Identification {
 14	
 15	    /** Dados da reserva necessários para emitir um documento. */
 16	    record Receipt(long reservationId, String guestName, int roomNumber, Domain.RoomType roomType,
 17	                   LocalDate checkIn, LocalDate checkOut, int nights,
 18	                   BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
 19	
 20	    String title();
 21	
 22	    String render(Receipt r);
 23	
 24	    default String cpf() { return null; }
 25	    default String cnpj() { return null; }
 26	    default String companyName() { return null; }
 27	    default String passport() { return null; }
 28	    default String country() { return null; }
 29	
 30	    DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 31	
 32	    static String digits(String s) {
 33	        return s.replaceAll("\\D", "");
 34	    }
 35	
 36	    static String formatCpf(String s) {
 37	        String d = digits(s);
 38	        return d.length() == 11
 39	                ? d.substring(0, 3) + "." + d.substring(3, 6) + "." + d.substring(6, 9) + "-" + d.substring(9)
 40	                : s;
 41	    }
 42	
 43	    static String formatCnpj(String s) {
 44	        String d = digits(s);
 45	        return d.length() == 14
 46	                ? d.substring(0, 2) + "." + d.substring(2, 5) + "." + d.substring(5, 8) + "/"
 47	                        + d.substring(8, 12) + "-" + d.substring(12)
 48	                : s;
 49	    }
 50	
 51	    /** Linhas comuns aos documentos em português. */
 52	    private static String ptBody(Receipt r) {
 53	        StringBuilder sb = new StringBuilder();
 54	        sb.append("Quarto: ").append(r.roomNumber()).append(" (").append(r.roomType()).append(")\n");
 55	        sb.append("Entrada: ").append(BR_DATE.format(r.checkIn()))
 56	          .append(" | Saída: ").append(BR_DATE.format(r.checkOut()))
 57	          .append(" | ").append(r.nights()).append(r.nights() == 1 ? " diária" : " diárias").append('\n');
 58	        sb.append("Diárias: R$ ").append(Money.br(r.subtotal())).append('\n');
 59	        if (r.discount().signum() > 0) {
 60	            sb.append("Desconto: R$ ").append(Money.br(r.discount())).append('\n');
 61	        }
 62	        sb.append("Total: R$ ").append(Money.br(r.total()));
 63	        return sb.toString();
 64	    }
 65	
 66	    /** Pessoa física, com CPF. */
 67	    record Individual(String cpf) implements Identification {
 68	        public String title() { return "Comprovante de reserva"; }
 69	
 70	        public String render(Receipt r) {
 71	            return "Comprovante de reserva nº " + r.reservationId() + "\n"
 72	                    + "Hóspede: " + r.guestName() + " (CPF " + formatCpf(cpf) + ")\n"
 73	                    + ptBody(r);
 74	        }
 75	    }
 76	
 77	    /** Empresa, com CNPJ; recebe fatura com ISS retido. */
 78	    record Company(String cnpj, String companyName) implements Identification {
 79	        private static final BigDecimal ISS = new BigDecimal("0.05");
 80	
 81	        public String title() { return "Fatura de hospedagem"; }
 82	
 83	        public String render(Receipt r) {
 84	            return "Fatura de hospedagem nº " + r.reservationId() + "\n"
 85	                    + "Empresa: " + companyName + " (CNPJ " + formatCnpj(cnpj) + ")\n"
 86	                    + "Hóspede: " + r.guestName() + "\n"
 87	                    + ptBody(r) + "\n"
 88	                    + "ISS retido (5%): R$ " + Money.br(Money.round(r.total().multiply(ISS)));
 89	        }
 90	    }
 91	
 92	    /** Estrangeiro, com passaporte; recebe o booking receipt em inglês. */
 93	    record Foreigner(String passport, String country) implements Identification {
 94	        private static final DateTimeFormatter ISO = DateTimeFormatter.ISO_LOCAL_DATE;
 95	
 96	        public String title() { return "Booking receipt"; }
 97	
 98	        public String render(Receipt r) {
 99	            StringBuilder sb = new StringBuilder();
100	            sb.append("Booking receipt no. ").append(r.reservationId()).append('\n');
101	            sb.append("Guest: ").append(r.guestName()).append(" (passport ").append(passport)
102	              .append(", ").append(country).append(")\n");
103	            sb.append("Room: ").append(r.roomNumber()).append(" (").append(r.roomType()).append(")\n");
104	            sb.append("Check-in: ").append(ISO.format(r.checkIn()))
105	              .append(" | Check-out: ").append(ISO.format(r.checkOut()))
106	              .append(" | ").append(r.nights()).append(r.nights() == 1 ? " night" : " nights").append('\n');
107	            sb.append("Nights: BRL ").append(Money.en(r.subtotal())).append('\n');
108	            if (r.discount().signum() > 0) {
109	                sb.append("Discount: BRL ").append(Money.en(r.discount())).append('\n');
110	            }
111	            sb.append("Total: BRL ").append(Money.en(r.total()));
112	            return sb.toString();
113	        }
114	    }
115	
116	    /** Monta a identificação a partir dos cinco campos (os não usados são null). */
117	    static Identification from(String cpf, String cnpj, String companyName, String passport, String country) {
118	        if (cpf != null) return new Individual(cpf);
119	        if (cnpj != null) return new Company(cnpj, companyName);
120	        return new Foreigner(passport, country);
121	    }
122	}
