155	import java.math.BigDecimal;
156	import java.math.RoundingMode;
157	
158	/** Valores em dinheiro: sempre 2 casas, arredondamento "meio para o par". */
159	public final class Money {
160	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
161	
162	    private Money() {}
163	
164	    public static BigDecimal round(BigDecimal v) {
165	        return v.setScale(2, RoundingMode.HALF_EVEN);
166	    }
167	
168	    public static BigDecimal of(String v) {
169	        return round(new BigDecimal(v));
170	    }
171	
172	    /** "1.234,56" (pt-BR) */
173	    public static String br(BigDecimal v) {
174	        return format(v, '.', ',');
175	    }
176	
177	    /** "1,234.56" (en) */
178	    public static String en(BigDecimal v) {
179	        return format(v, ',', '.');
180	    }
181	
182	    /** "1234.56" (CSV) */
183	    public static String plain(BigDecimal v) {
184	        return round(v).toPlainString();
185	    }
186	
187	    private static String format(BigDecimal v, char group, char decimal) {
188	        String plain = round(v).abs().toPlainString();
189	        int dot = plain.indexOf('.');
190	        String ints = plain.substring(0, dot);
191	        String frac = plain.substring(dot + 1);
192	        StringBuilder sb = new StringBuilder();
193	        for (int i = 0; i < ints.length(); i++) {
194	            if (i > 0 && (ints.length() - i) % 3 == 0) sb.append(group);
195	            sb.append(ints.charAt(i));
196	        }
197	        return (v.signum() < 0 ? "-" : "") + sb + decimal + frac;
198	    }
199	}
